import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> dict(side, price, qty, active)
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_valid_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return negprice, seq, oid
        return None

    def pop_valid_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return price, seq, oid
